import assert from 'node:assert/strict';
import { Mistral } from '@mistralai/mistralai';
if (!process.env.VOLTER_WORLD) throw new Error('Run this application through its World.');
assert.ok(process.env.MISTRAL_API_KEY, 'the application receives its own API key');
const client = new Mistral({ apiKey: process.env.MISTRAL_API_KEY });
const model = 'mistral-small-latest';
const prompt = 'Explain the purpose of this customer workflow.';
const messages = [{ role: 'user', content: prompt }];
const expected = '[twin-stub:' + model + '] This is a deterministic stub from the Mistral API twin (no model runs). Your last message: ' + prompt;
const response = await client.chat.complete({ model, messages });
assert.equal(response.model, model);
assert.equal(response.choices[0].message.content, expected);
assert.equal(response.choices[0].finishReason, 'stop');
assert.ok(response.usage.promptTokens > 0 && response.usage.completionTokens > 0);
const stream = await client.chat.stream({ model, messages });
let text = '', finishReason, usage;
for await (const event of stream) {
  for (const choice of event.data.choices) {
    text += choice.delta.content ?? '';
    finishReason = choice.finishReason ?? finishReason;
  }
  if (event.data.usage) usage = event.data.usage;
}
assert.equal(text, expected);
assert.equal(finishReason, 'stop');
assert.ok(usage.promptTokens > 0 && usage.completionTokens > 0);
console.log(JSON.stringify({ model, text, finishReason, usage }));
